    const caja=(n,x,y,hub)=>{const w=Math.max(96,n.length*8.2+30);
      return `<g class="nd${hub?' hubn':''}" style="transition-delay:${hub?0:.3}s"><rect x="${x-w/2}" y="${y-19}" width="${w}" height="38" rx="3"/><text x="${x}" y="${y+5}" text-anchor="middle">${esc(n)}</text></g>`;};
    const L=(x1,y1,x2,y2,cl)=>{const l=Math.hypot(x2-x1,y2-y1);return `<line class="${cl||''}" x1="${x1}" y1="${y1}" x2="${x2}" y2="${y2}" style="--l:${l.toFixed(0)}"/>`;};
    let s=P.map(p=>L(cx,cy,p.x,p.y,'hub')).join('')+P.map((p,i)=>{const q=P[(i+1)%P.length];return L(p.x,p.y,q.x,q.y);}).join('');
