/* ═══ acerca de: ruta, imágenes, lectura y tono ═══ */
(function(){
  const ac=document.getElementById('ac'); if(!ac) return; const cb=document.getElementById('cb');
  const fuente=k=>{ if(k.startsWith('#')){const i=document.querySelector(k+' img');return i?i.currentSrc||i.src:'';}
    const a=[...document.querySelectorAll('#industrias-esc .esc-f, #industrias-esc-img .esc-f')].find(x=>(x.getAttribute('aria-label')||'').startsWith(k+':'));const i=a&&a.querySelector('img');return i?i.currentSrc||i.src:''; };
  let cargadas=false;
  function imagenes(){ if(cargadas) return; ac.querySelectorAll('[data-img]').forEach(el=>{const img=el.tagName==='IMG'?el:el.querySelector('img');const s=fuente(el.dataset.img);if(img&&s)img.src=s;}); cargadas=true; }
  const fr=document.getElementById('acFrase'), W=fr?[...fr.querySelectorAll('span')]:[];
  const quieto=matchMedia('(prefers-reduced-motion: reduce)').matches;
  function lectura(){ if(!fr||quieto) return; const r=fr.getBoundingClientRect(),vh=ac.clientHeight;
    const p=Math.min(1,Math.max(0,(vh*.85-r.top)/(r.height+vh*.35))); const n=Math.round(p*W.length); W.forEach((w,i)=>w.classList.toggle('on',i<n)); }
  const tono=()=>{ if(!cb||ac.hidden) return; const y=cb.getBoundingClientRect().bottom-10;
    const os=[...ac.querySelectorAll('[data-tono="oscuro"]')].some(s=>{const r=s.getBoundingClientRect();return r.top<=y&&r.bottom>y;}); cb.classList.toggle('claro',!os); };

  /* interludio: Registra. Entiende. Decide. */
  const PAL=[...ac.querySelectorAll('.ac3-pal span')];
  function interludio(){ const el=document.getElementById('acInt'); if(!el||!PAL.length) return; if(quieto){PAL.forEach(p=>p.classList.add('on'));return;}
    const r=el.getBoundingClientRect(),vh=ac.clientHeight; const p=Math.min(1,Math.max(0,(vh*.75-r.top)/(r.height*.7)));
    PAL.forEach((w,i)=>w.classList.toggle('on',p>(i+.4)/PAL.length)); }
  ac.addEventListener('scroll',interludio,{passive:true});
  /* índice de capítulos */
  ac.querySelectorAll('.ac3-ind a').forEach(a=>a.addEventListener('click',e=>{e.preventDefault();
    const t=ac.querySelector('[data-ci="'+a.dataset.cap+'"]'); if(t) ac.scrollTo({top:t.offsetTop-70,behavior:'smooth'});}));
  ac.addEventListener('scroll',()=>{tono();lectura();},{passive:true});
  const obs=new IntersectionObserver(es=>es.forEach(e=>{if(e.isIntersecting){e.target.classList.add('vis');obs.unobserve(e.target);}}),{root:ac,threshold:.12});
  ac.querySelectorAll('.rv').forEach(x=>obs.observe(x));
  function abre(){ imagenes(); ac.hidden=false; ac.scrollTop=0; document.documentElement.classList.add('en-acerca');
    requestAnimationFrame(()=>{ac.classList.add('abierto');tono();lectura();}); document.title='Acerca de · Pahlass'; }
  function cierra(){ if(ac.hidden) return; ac.classList.remove('abierto'); document.documentElement.classList.remove('en-acerca');
    setTimeout(()=>{if(!ac.classList.contains('abierto'))ac.hidden=true;},450); if(!/^#(caso|prensa)/.test(location.hash)){document.title='Pahlass | Sistema de orquestación de datos multidominio';window.dispatchEvent(new Event('scroll'));} }
  function ruta(){ if(location.hash==='#acerca') abre(); else cierra(); }
  addEventListener('hashchange',ruta);
  document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!ac.hidden&&document.getElementById('cbPanel').hidden) location.hash='despliegue';});
  ruta();
})();
